//! Byte transports (architecture D2) and bus ownership.
//!
//! Serial (Windows, Android) transports live in the app crates; this module
//! has the trait, a scripted fake, a Modbus TCP client and the exchanger that
//! runs one request/response over any transport.

pub mod exchange;
pub mod fake;
pub mod tcp;

use std::collections::HashSet;
use std::sync::{Arc, Mutex};
use thiserror::Error;

#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum TransportError {
    /// The port or connection is gone (USB detach, socket closed).
    #[error("link disconnected: {0}")]
    Disconnected(String),
    #[error("permission denied")]
    PermissionDenied,
    #[error("I/O error: {0}")]
    Io(String),
}

pub trait Transport: Send {
    /// Write all bytes or fail.
    fn write_all(&mut self, bytes: &[u8]) -> Result<(), TransportError>;

    /// Read up to `buf.len()` bytes, waiting at most `timeout_ms`.
    /// `Ok(0)` means nothing arrived before the timeout; it is not end of stream.
    fn read(&mut self, buf: &mut [u8], timeout_ms: u64) -> Result<usize, TransportError>;

    /// Discard stale input by reading until the line has been quiet for
    /// `quiet_ms` (no hardware purge: the CH340 driver on Android throws on it).
    /// Bounded to 16 reads. Returns the number of discarded bytes.
    fn drain(&mut self, quiet_ms: u64) -> Result<usize, TransportError> {
        let mut buf = [0u8; 256];
        let mut total = 0;
        for _ in 0..16 {
            let n = self.read(&mut buf, quiet_ms)?;
            if n == 0 {
                break;
            }
            total += n;
        }
        Ok(total)
    }

    fn close(&mut self) {}
}

impl<T: Transport + ?Sized> Transport for Box<T> {
    fn write_all(&mut self, bytes: &[u8]) -> Result<(), TransportError> {
        (**self).write_all(bytes)
    }
    fn read(&mut self, buf: &mut [u8], timeout_ms: u64) -> Result<usize, TransportError> {
        (**self).read(buf, timeout_ms)
    }
    fn drain(&mut self, quiet_ms: u64) -> Result<usize, TransportError> {
        (**self).drain(quiet_ms)
    }
    fn close(&mut self) {
        (**self).close()
    }
}

#[derive(Debug, Error, Clone, PartialEq, Eq)]
#[error("'{0}' is already owned by another worker (one master per bus)")]
pub struct AlreadyOwned(pub String);

/// Process-wide record of which buses have an owner (safety rule 9).
#[derive(Debug, Default)]
pub struct LinkRegistry {
    owned: Mutex<HashSet<String>>,
}

impl LinkRegistry {
    pub fn new() -> Arc<Self> {
        Arc::new(Self::default())
    }

    pub fn claim(self: &Arc<Self>, key: &str) -> Result<LinkClaim, AlreadyOwned> {
        let mut owned = self.owned.lock().unwrap_or_else(|e| e.into_inner());
        if !owned.insert(key.to_owned()) {
            return Err(AlreadyOwned(key.to_owned()));
        }
        Ok(LinkClaim {
            registry: Arc::clone(self),
            key: key.to_owned(),
        })
    }

    pub fn is_owned(&self, key: &str) -> bool {
        self.owned.lock().unwrap_or_else(|e| e.into_inner()).contains(key)
    }
}

/// Ownership of one bus; released on drop.
#[derive(Debug)]
pub struct LinkClaim {
    registry: Arc<LinkRegistry>,
    key: String,
}

impl LinkClaim {
    pub fn key(&self) -> &str {
        &self.key
    }
}

impl Drop for LinkClaim {
    fn drop(&mut self) {
        self.registry
            .owned
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .remove(&self.key);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn one_owner_per_key() {
        let reg = LinkRegistry::new();
        let a = reg.claim("serial:com7").unwrap();
        assert_eq!(
            reg.claim("serial:com7").unwrap_err(),
            AlreadyOwned("serial:com7".into())
        );
        let _b = reg.claim("serial:com8").unwrap();
        drop(a);
        assert!(!reg.is_owned("serial:com7"));
        assert!(reg.claim("serial:com7").is_ok());
    }
}
//! Sample bus (architecture D4): one broadcast stream of samples, so the UI,
//! historian, LAN view and MQTT all see the same values and qualities.
//! Uses `tokio::sync::broadcast` without a runtime; a lagging subscriber is
//! told how many samples it missed instead of losing them silently.

use crate::quality::Sample;
use std::sync::Arc;
use tokio::sync::broadcast::{self, error::TryRecvError};

pub const DEFAULT_CAPACITY: usize = 4096;

#[derive(Clone)]
pub struct SampleBus {
    tx: broadcast::Sender<Arc<Sample>>,
}

#[derive(Debug, PartialEq)]
pub enum BusRecv {
    Sample(Arc<Sample>),
    /// This many samples were overwritten before this subscriber read them.
    Lagged(u64),
    Empty,
    Closed,
}

pub struct BusSubscriber {
    rx: broadcast::Receiver<Arc<Sample>>,
}

impl SampleBus {
    pub fn new(capacity: usize) -> Self {
        let (tx, _) = broadcast::channel(capacity.max(1));
        Self { tx }
    }

    /// Publish to every subscriber; returns how many will see it.
    pub fn publish(&self, sample: Sample) -> usize {
        self.tx.send(Arc::new(sample)).unwrap_or(0)
    }

    pub fn subscribe(&self) -> BusSubscriber {
        BusSubscriber {
            rx: self.tx.subscribe(),
        }
    }

    /// A sink for [`crate::poll::worker::LinkWorker::spawn`].
    pub fn sink(&self) -> crate::poll::worker::SampleSink {
        let bus = self.clone();
        Arc::new(move |s| {
            bus.publish(s);
        })
    }
}

impl Default for SampleBus {
    fn default() -> Self {
        Self::new(DEFAULT_CAPACITY)
    }
}

impl BusSubscriber {
    pub fn try_recv(&mut self) -> BusRecv {
        match self.rx.try_recv() {
            Ok(s) => BusRecv::Sample(s),
            Err(TryRecvError::Lagged(n)) => BusRecv::Lagged(n),
            Err(TryRecvError::Empty) => BusRecv::Empty,
            Err(TryRecvError::Closed) => BusRecv::Closed,
        }
    }

    /// Blocking receive (call from a plain thread, never inside an async runtime).
    pub fn recv_blocking(&mut self) -> BusRecv {
        match self.rx.blocking_recv() {
            Ok(s) => BusRecv::Sample(s),
            Err(broadcast::error::RecvError::Lagged(n)) => BusRecv::Lagged(n),
            Err(broadcast::error::RecvError::Closed) => BusRecv::Closed,
        }
    }

    /// Everything currently queued (lag notices included).
    pub fn drain(&mut self) -> Vec<BusRecv> {
        let mut out = Vec::new();
        loop {
            match self.try_recv() {
                BusRecv::Empty => break,
                BusRecv::Closed => {
                    out.push(BusRecv::Closed);
                    break;
                }
                other => out.push(other),
            }
        }
        out
    }
}
//! Polling: block planning, the per-link scheduler and its worker thread.

pub mod plan;
pub mod scheduler;
pub mod worker;
//! The link worker: a dedicated thread that owns the transport and runs the
//! scheduler (blocking serial I/O stays off any async runtime). Every read and
//! write for the link goes through its single queue (safety rule 9).

use super::scheduler::{DeviceCounters, LinkScheduler, Priority, Step, UrgentJob};
use crate::command::{CommandLink, PreparedFrame};
use crate::protocol::pdu::{ReadData, ReadRequest};
use crate::quality::Sample;
use crate::transport::exchange::{ExchangeError, ExchangeRecord};
use crate::transport::{LinkClaim, Transport, TransportError};
use std::sync::mpsc::{self, RecvTimeoutError};
use std::sync::{Arc, Mutex};
use std::thread::JoinHandle;
use std::time::Duration;

enum Msg {
    Job(UrgentJob),
    Stop,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LinkState {
    Running,
    /// The transport failed (detach, socket closed). Reconnect means a new worker.
    Down,
    Stopped,
}

#[derive(Clone, Debug)]
pub struct LinkStatus {
    pub state: LinkState,
    pub counters: Vec<(String, DeviceCounters)>,
}

pub type SampleSink = Arc<dyn Fn(Sample) + Send + Sync>;

pub struct LinkWorker {
    tx: mpsc::Sender<Msg>,
    status: Arc<Mutex<LinkStatus>>,
    handle: Option<JoinHandle<()>>,
}

/// Cheap, cloneable way to submit jobs to a running worker.
#[derive(Clone)]
pub struct LinkHandle {
    tx: mpsc::Sender<Msg>,
    /// Timeout for jobs submitted through this handle.
    pub timeout_ms: u64,
}

impl LinkWorker {
    /// Start the worker. `claim` proves this worker is the only master on the bus;
    /// it is released when the thread ends.
    pub fn spawn(
        claim: LinkClaim,
        mut scheduler: LinkScheduler,
        mut transport: Box<dyn Transport>,
        sink: SampleSink,
    ) -> std::io::Result<LinkWorker> {
        let (tx, rx) = mpsc::channel::<Msg>();
        let status = Arc::new(Mutex::new(LinkStatus {
            state: LinkState::Running,
            counters: scheduler.counters(),
        }));
        let st = Arc::clone(&status);
        let name = format!("buslink-link-{}", scheduler.link().id);
        let handle = std::thread::Builder::new().name(name).spawn(move || {
            let _claim = claim;
            let mut emit = |s: Sample| sink(s);
            let mut final_state = LinkState::Stopped;
            'run: loop {
                loop {
                    match rx.try_recv() {
                        Ok(Msg::Job(job)) => scheduler.submit(job),
                        Ok(Msg::Stop) | Err(mpsc::TryRecvError::Disconnected) => break 'run,
                        Err(mpsc::TryRecvError::Empty) => break,
                    }
                }
                let step = scheduler.step(transport.as_mut(), &mut emit);
                if let Ok(mut s) = st.lock() {
                    s.counters = scheduler.counters();
                }
                match step {
                    Step::Worked => {}
                    Step::LinkDown => {
                        final_state = LinkState::Down;
                        break 'run;
                    }
                    Step::Idle { until_mono_ms } => {
                        let wait = until_mono_ms.saturating_sub(scheduler.clock_mono());
                        match rx.recv_timeout(Duration::from_millis(wait.clamp(1, 1000))) {
                            Ok(Msg::Job(job)) => scheduler.submit(job),
                            Ok(Msg::Stop) | Err(RecvTimeoutError::Disconnected) => break 'run,
                            Err(RecvTimeoutError::Timeout) => {}
                        }
                    }
                }
            }
            scheduler.fail_pending();
            // Jobs that raced in after the decision to stop also fail; nothing is replayed.
            while let Ok(msg) = rx.try_recv() {
                if let Msg::Job(job) = msg {
                    scheduler.submit(job);
                    scheduler.fail_pending();
                }
            }
            transport.close();
            if let Ok(mut s) = st.lock() {
                s.state = final_state;
                s.counters = scheduler.counters();
            }
        })?;
        Ok(LinkWorker {
            tx,
            status,
            handle: Some(handle),
        })
    }

    pub fn handle(&self, timeout_ms: u64) -> LinkHandle {
        LinkHandle {
            tx: self.tx.clone(),
            timeout_ms,
        }
    }

    pub fn status(&self) -> LinkStatus {
        self.status.lock().unwrap_or_else(|e| e.into_inner()).clone()
    }

    pub fn is_finished(&self) -> bool {
        self.handle.as_ref().is_none_or(|h| h.is_finished())
    }

    /// Stop polling, fail queued jobs, close the transport and wait for the thread.
    pub fn stop(mut self) -> LinkStatus {
        let _ = self.tx.send(Msg::Stop);
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
        self.status()
    }
}

impl Drop for LinkWorker {
    fn drop(&mut self) {
        let _ = self.tx.send(Msg::Stop);
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

fn lost() -> ExchangeError {
    ExchangeError::Link(TransportError::Disconnected("link worker stopped".into()))
}

impl LinkHandle {
    /// Read at the given priority and wait for the result.
    pub fn read(&self, unit: u8, request: ReadRequest, priority: Priority) -> Result<ReadData, ExchangeError> {
        let (tx, rx) = mpsc::sync_channel(1);
        let job = UrgentJob::Read {
            unit,
            request,
            priority,
            timeout_ms: self.timeout_ms,
            reply: Box::new(move |r| {
                let _ = tx.send(r);
            }),
        };
        self.tx.send(Msg::Job(job)).map_err(|_| lost())?;
        rx.recv().unwrap_or_else(|_| Err(lost()))
    }

    /// Hand a confirmed frame to the worker; it is sent once.
    pub fn send_command(&self, frame: PreparedFrame) -> ExchangeRecord {
        let unit = frame.unit();
        let pdu = frame.pdu().to_vec();
        let (tx, rx) = mpsc::sync_channel(1);
        let job = UrgentJob::Command {
            frame,
            timeout_ms: self.timeout_ms,
            reply: Box::new(move |r| {
                let _ = tx.send(r);
            }),
        };
        let not_sent = |request: Vec<u8>| ExchangeRecord {
            unit,
            request,
            response: Vec::new(),
            started_mono_ms: 0,
            elapsed_ms: 0,
            discarded: 0,
            outcome: Err(lost()),
        };
        if self.tx.send(Msg::Job(job)).is_err() {
            return not_sent(Vec::new());
        }
        // If the reply never comes the worker died mid-job: the effect is unknown,
        // so the record carries the PDU (not an empty "not sent" request).
        rx.recv().unwrap_or_else(|_| not_sent(pdu))
    }
}

impl CommandLink for LinkHandle {
    fn read(&mut self, unit: u8, request: ReadRequest) -> Result<ReadData, ExchangeError> {
        LinkHandle::read(self, unit, request, Priority::Command)
    }

    fn send(&mut self, frame: PreparedFrame) -> ExchangeRecord {
        self.send_command(frame)
    }
}


