//! The simulated bus: devices by unit ID, a fixed-step process clock, faults
//! and a seed. Same seed + same requests at the same times → identical bytes.

use crate::devices::{self, STEP_MS, SimModel};
use crate::fault::{FaultError, FaultId, FaultRule, FaultTable};
use crate::image::RegisterImage;
use crate::server;
use buslink_core::protocol::pdu::{ExceptionCode, exception_response};
use buslink_core::protocol::rtu;
use buslink_core::rng::{GOLDEN_GAMMA, SplitMix64};
use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};
use thiserror::Error;

/// Device turnaround added to every reply.
pub const TURNAROUND_MS: u64 = 5;
/// Longest catch-up in one `advance_to` call (1 h of simulated time); beyond
/// that the process jumps instead of stepping, so a paused world never stalls.
const MAX_STEPS_PER_ADVANCE: u64 = 36_000;

#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum WorldError {
    #[error("unit ID {0} is outside 1..=247")]
    UnitRange(u8),
    #[error("unit ID {0} is already used")]
    UnitTaken(u8),
    #[error("unknown simulator model '{0}'")]
    UnknownModel(String),
    #[error(transparent)]
    Fault(#[from] FaultError),
}

struct SimDevice {
    model: Box<dyn SimModel>,
    rng: SplitMix64,
    requests: u64,
}

/// Result of one request.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Reply {
    /// `None`: the device stays silent.
    pub pdu: Option<Vec<u8>>,
    pub delay_ms: u64,
    /// The transport must corrupt the frame (CRC on RTU, byte count on MBAP).
    pub corrupt: bool,
}

impl Reply {
    fn silent() -> Self {
        Self {
            pdu: None,
            delay_ms: 0,
            corrupt: false,
        }
    }
}

pub struct SimWorld {
    seed: u64,
    devices: BTreeMap<u8, SimDevice>,
    faults: FaultTable,
    fault_rng: SplitMix64,
    last_step_ms: Option<u64>,
}

pub type SharedWorld = Arc<Mutex<SimWorld>>;

impl SimWorld {
    pub fn new(seed: u64) -> Self {
        Self {
            seed,
            devices: BTreeMap::new(),
            faults: FaultTable::default(),
            fault_rng: SplitMix64::new(seed ^ 0xFA17),
            last_step_ms: None,
        }
    }

    pub fn shared(self) -> SharedWorld {
        Arc::new(Mutex::new(self))
    }

    /// The four training devices at their profile unit IDs: soil 1, VFD 2, temperature 3, meter 4.
    pub fn training(seed: u64) -> Self {
        let mut w = Self::new(seed);
        for (unit, model) in [
            (1, "bgt_smps_8in1"),
            (2, "vfd_basic"),
            (3, "temp_controller_basic"),
            (4, "energy_meter_basic"),
        ] {
            // Units are distinct and in range; the error branch cannot trigger.
            let _ = w.add_model(unit, model);
        }
        w
    }

    pub fn seed(&self) -> u64 {
        self.seed
    }

    pub fn add_device(&mut self, unit: u8, model: Box<dyn SimModel>) -> Result<(), WorldError> {
        if !(1..=247).contains(&unit) {
            return Err(WorldError::UnitRange(unit));
        }
        if self.devices.contains_key(&unit) {
            return Err(WorldError::UnitTaken(unit));
        }
        let rng = SplitMix64::new(self.seed ^ u64::from(unit).wrapping_mul(GOLDEN_GAMMA));
        self.devices.insert(
            unit,
            SimDevice {
                model,
                rng,
                requests: 0,
            },
        );
        Ok(())
    }

    pub fn add_model(&mut self, unit: u8, model_id: &str) -> Result<(), WorldError> {
        let model = devices::create(model_id).ok_or_else(|| WorldError::UnknownModel(model_id.to_owned()))?;
        self.add_device(unit, model)
    }

    pub fn units(&self) -> Vec<u8> {
        self.devices.keys().copied().collect()
    }

    pub fn model_id(&self, unit: u8) -> Option<&'static str> {
        self.devices.get(&unit).map(|d| d.model.model_id())
    }

    pub fn add_fault(&mut self, rule: FaultRule) -> Result<FaultId, WorldError> {
        Ok(self.faults.add(rule)?)
    }

    pub fn remove_fault(&mut self, id: FaultId) -> bool {
        self.faults.remove(id)
    }

    pub fn clear_faults(&mut self, unit: u8) {
        self.faults.clear_unit(unit);
    }

    /// Typed access to a model (training scenarios, tests).
    pub fn with_model<T: 'static, R>(&mut self, unit: u8, f: impl FnOnce(&mut T) -> R) -> Option<R> {
        let d = self.devices.get_mut(&unit)?;
        d.model.as_any_mut().downcast_mut::<T>().map(f)
    }

    pub fn image(&self, unit: u8) -> Option<RegisterImage> {
        self.devices.get(&unit).map(|d| d.model.image(false))
    }

    /// Run fixed 100 ms steps up to `now_ms`. Devices under the stale fault are not stepped.
    pub fn advance_to(&mut self, now_ms: u64) {
        let Some(mut last) = self.last_step_ms else {
            self.last_step_ms = Some(now_ms);
            return;
        };
        if now_ms <= last {
            return;
        }
        let mut steps = (now_ms - last) / STEP_MS;
        if steps > MAX_STEPS_PER_ADVANCE {
            last += (steps - MAX_STEPS_PER_ADVANCE) * STEP_MS;
            steps = MAX_STEPS_PER_ADVANCE;
        }
        for _ in 0..steps {
            last += STEP_MS;
            for (unit, d) in self.devices.iter_mut() {
                if !self.faults.stale(*unit, last, d.requests) {
                    d.model.step(STEP_MS, &mut d.rng);
                }
            }
        }
        self.last_step_ms = Some(last);
    }

    /// Handle one request PDU addressed to `unit` at simulated time `now_ms`.
    pub fn handle_pdu(&mut self, unit: u8, pdu: &[u8], now_ms: u64) -> Reply {
        self.advance_to(now_ms);
        if unit == 0 {
            // Broadcast: writes apply to every device, nobody answers (serial line spec).
            if pdu.first().is_some_and(|fc| matches!(fc, 0x05 | 0x06 | 0x0F | 0x10)) {
                for d in self.devices.values_mut() {
                    let _ = server::handle(d.model.as_mut(), pdu, false);
                }
            }
            return Reply::silent();
        }
        let Some(d) = self.devices.get_mut(&unit) else {
            return Reply::silent();
        };
        let request = d.requests;
        d.requests += 1;
        let effect = self.faults.evaluate(unit, now_ms, request, &mut self.fault_rng);
        if effect.silent {
            return Reply::silent();
        }
        let pdu = match effect.exception {
            Some(code) => exception_response(pdu.first().copied().unwrap_or(0), ExceptionCode(code)).to_vec(),
            None => server::handle(d.model.as_mut(), pdu, effect.wrong_order),
        };
        Reply {
            pdu: Some(pdu),
            delay_ms: TURNAROUND_MS + effect.delay_ms,
            corrupt: effect.corrupt,
        }
    }

    /// Handle one RTU ADU. Bad CRC or unknown unit → silence.
    /// Returns the reply ADU and its delay.
    pub fn handle_rtu(&mut self, adu: &[u8], now_ms: u64) -> Option<(Vec<u8>, u64)> {
        let (unit, pdu) = match rtu::decode_adu(adu) {
            Ok(x) => x,
            Err(_) => {
                self.advance_to(now_ms);
                return None;
            }
        };
        let reply = self.handle_pdu(unit, pdu, now_ms);
        let pdu = reply.pdu?;
        let mut out = rtu::encode_adu(unit, &pdu).ok()?;
        if reply.corrupt {
            let last = out.len() - 1;
            out[last] ^= 0x5A;
        }
        Some((out, reply.delay_ms))
    }
}
//! Fault injection (PRD R24). Faults change how a device answers, never its register map.

use buslink_core::rng::SplitMix64;
use thiserror::Error;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FaultKind {
    /// No reply.
    Timeout,
    /// Reply with a corrupted CRC (RTU) or a corrupted byte count (MBAP).
    CrcError,
    /// Reply with this exception code.
    Exception(u8),
    /// Process values frozen while replies continue (a gateway serving a cache).
    Stale,
    /// 32/64-bit values word-swapped, 16-bit registers byte-swapped.
    WrongOrder,
    /// Reply after an extra delay (to land after the client timeout).
    LateReply { delay_ms: u64 },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Trigger {
    Always,
    /// Per request, drawn from the world's seeded fault generator.
    Probability {
        per_mille: u16,
    },
    /// Simulated time window `[from_ms, until_ms)` on the world clock.
    Window {
        from_ms: u64,
        until_ms: u64,
    },
    /// Requests `skip .. skip + count` to this unit (0-based).
    Requests {
        skip: u64,
        count: u64,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FaultRule {
    pub unit: u8,
    pub kind: FaultKind,
    pub trigger: Trigger,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FaultId(pub u64);

#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum FaultError {
    #[error("the stale fault needs a deterministic trigger (always, window or request count)")]
    StaleNeedsDeterministicTrigger,
    #[error("probability {0} is above 1000 per mille")]
    Probability(u16),
}

#[derive(Default)]
pub struct FaultTable {
    rules: Vec<(FaultId, FaultRule)>,
    next: u64,
}

/// The effect of the faults active for one request.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Effect {
    pub silent: bool,
    pub corrupt: bool,
    pub exception: Option<u8>,
    pub delay_ms: u64,
    pub wrong_order: bool,
}

impl FaultTable {
    pub fn add(&mut self, rule: FaultRule) -> Result<FaultId, FaultError> {
        if let Trigger::Probability { per_mille } = rule.trigger {
            if rule.kind == FaultKind::Stale {
                return Err(FaultError::StaleNeedsDeterministicTrigger);
            }
            if per_mille > 1000 {
                return Err(FaultError::Probability(per_mille));
            }
        }
        self.next += 1;
        let id = FaultId(self.next);
        self.rules.push((id, rule));
        Ok(id)
    }

    pub fn remove(&mut self, id: FaultId) -> bool {
        let before = self.rules.len();
        self.rules.retain(|(i, _)| *i != id);
        self.rules.len() != before
    }

    pub fn clear_unit(&mut self, unit: u8) {
        self.rules.retain(|(_, r)| r.unit != unit);
    }

    pub fn is_empty(&self) -> bool {
        self.rules.is_empty()
    }

    fn static_active(t: Trigger, now_ms: u64, request: u64) -> bool {
        match t {
            Trigger::Always => true,
            Trigger::Window { from_ms, until_ms } => (from_ms..until_ms).contains(&now_ms),
            Trigger::Requests { skip, count } => request >= skip && request - skip < count,
            Trigger::Probability { .. } => false,
        }
    }

    /// Is the device frozen right now? (`request` = requests handled so far.)
    pub fn stale(&self, unit: u8, now_ms: u64, request: u64) -> bool {
        self.rules.iter().any(|(_, r)| {
            r.unit == unit && r.kind == FaultKind::Stale && Self::static_active(r.trigger, now_ms, request)
        })
    }

    /// Effect for request number `request` (0-based) to `unit`. The first active
    /// reply-shaping rule (timeout, CRC, exception, late reply) wins.
    pub fn evaluate(&self, unit: u8, now_ms: u64, request: u64, rng: &mut SplitMix64) -> Effect {
        let mut e = Effect::default();
        let mut shaped = false;
        for (_, r) in self.rules.iter().filter(|(_, r)| r.unit == unit) {
            let active = match r.trigger {
                // Every probabilistic rule draws, active or not, so sequences stay reproducible.
                Trigger::Probability { per_mille } => rng.chance(per_mille),
                t => Self::static_active(t, now_ms, request),
            };
            if !active {
                continue;
            }
            match r.kind {
                FaultKind::WrongOrder => e.wrong_order = true,
                FaultKind::Stale => {}
                _ if shaped => {}
                FaultKind::Timeout => {
                    e.silent = true;
                    shaped = true;
                }
                FaultKind::CrcError => {
                    e.corrupt = true;
                    shaped = true;
                }
                FaultKind::Exception(c) => {
                    e.exception = Some(c);
                    shaped = true;
                }
                FaultKind::LateReply { delay_ms } => {
                    e.delay_ms = delay_ms;
                    shaped = true;
                }
            }
        }
        e
    }
}
//! In-memory transport to a simulated bus, implementing the core `Transport`.
//! RTU requests are framed by function code; replies can be split into
//! seeded random chunks to mimic USB packet fragmentation.

use crate::world::SharedWorld;
use buslink_core::clock::Clock;
use buslink_core::protocol::tcp::{self, MbapReceiver};
use buslink_core::rng::SplitMix64;
use buslink_core::transport::{Transport, TransportError};
use std::collections::VecDeque;
use std::sync::Arc;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Chunking {
    Whole,
    /// Split every reply into pieces of 1..=max bytes.
    Random {
        max: usize,
        seed: u64,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Mode {
    Rtu,
    Mbap,
}

pub struct SimTransport {
    world: SharedWorld,
    clock: Arc<dyn Clock>,
    mode: Mode,
    chunk_max: usize,
    rng: SplitMix64,
    rx: Vec<u8>,
    mbap: MbapReceiver,
    pending: VecDeque<(u64, Vec<u8>)>,
    closed: bool,
}

/// Length of the RTU request starting at `buf[0]`, if it can be known yet.
/// Unknown function codes take the whole buffer (the slave then ignores it on CRC).
fn rtu_request_len(buf: &[u8]) -> Option<usize> {
    let fc = *buf.get(1)?;
    match fc {
        0x01..=0x06 => Some(8),
        0x0F | 0x10 => buf.get(6).map(|&n| 9 + usize::from(n)),
        _ => Some(buf.len()),
    }
}

impl SimTransport {
    fn new(world: SharedWorld, clock: Arc<dyn Clock>, mode: Mode, chunking: Chunking) -> Self {
        let (chunk_max, seed) = match chunking {
            Chunking::Whole => (0, 0),
            Chunking::Random { max, seed } => (max.max(1), seed),
        };
        Self {
            world,
            clock,
            mode,
            chunk_max,
            rng: SplitMix64::new(seed),
            rx: Vec::new(),
            mbap: MbapReceiver::new(),
            pending: VecDeque::new(),
            closed: false,
        }
    }

    /// A simulated RS485 bus with RTU framing.
    pub fn rtu(world: SharedWorld, clock: Arc<dyn Clock>, chunking: Chunking) -> Self {
        Self::new(world, clock, Mode::Rtu, chunking)
    }

    /// A simulated Modbus TCP connection (MBAP framing).
    pub fn mbap(world: SharedWorld, clock: Arc<dyn Clock>) -> Self {
        Self::new(world, clock, Mode::Mbap, Chunking::Whole)
    }



