#[derive(serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PortInfo {
    name: String,
    vid: Option<u16>,
    pid: Option<u16>,
    serial_number: Option<String>,
    manufacturer: Option<String>,
    product: Option<String>,
    attachment_id: Option<u64>,
}
#[tauri::command]
pub async fn port_inventory(app: tauri::AppHandle) -> Result<Vec<PortInfo>, String> {
    #[cfg(not(target_os = "android"))]
    let _ = &app;
    #[cfg(windows)]
    {
        serialport::available_ports()
            .map(|ports| {
                ports
                    .into_iter()
                    .map(|port| {
                        let mut info = PortInfo {
                            name: port.port_name,
                            vid: None,
                            pid: None,
                            serial_number: None,
                            manufacturer: None,
                            product: None,
                            attachment_id: None,
                        };
                        if let serialport::SerialPortType::UsbPort(usb) = port.port_type {
                            info.vid = Some(usb.vid);
                            info.pid = Some(usb.pid);
                            info.serial_number = usb.serial_number;
                            info.manufacturer = usb.manufacturer;
                            info.product = usb.product;
                        }
                        info
                    })
                    .collect()
            })
            .map_err(|e| e.to_string())
    }
    #[cfg(target_os = "android")]
    {
        tauri::async_runtime::spawn_blocking(move || crate::usb::inventory(&app))
            .await.map_err(|e| e.to_string())?
    }
    #[cfg(not(any(windows, target_os = "android")))]
    {
        Err("Port COM hanya tersedia pada Windows".into())
    }
}
#[tauri::command]
pub fn startup_options() -> bool {
    std::env::var("SOIL_SENSOR_AUTOCONNECT").as_deref() != Ok("0")
}
