//! Logging interval and batching in front of the historian.
//!
//! `LogDecimator` stores a sample when its quality differs from the last
//! stored one for that tag (so every gap start and end is kept) or when the
//! logging interval has passed. `SampleBatcher` groups samples into one
//! transaction per second (architecture D9).

use crate::quality::{Quality, Sample};
use std::collections::HashMap;

pub struct LogDecimator {
    interval_ms: u64,
    last: HashMap<(String, String), (i64, Quality)>,
}

impl LogDecimator {
    pub fn new(interval_ms: u64) -> Self {
        Self {
            interval_ms,
            last: HashMap::new(),
        }
    }

    pub fn keep(&mut self, s: &Sample) -> bool {
        let key = (s.device_id.clone(), s.tag_id.clone());
        let keep = match self.last.get(&key) {
            None => true,
            Some((ts, q)) => {
                *q != s.quality || s.ts_ms.saturating_sub(*ts) >= i64::try_from(self.interval_ms).unwrap_or(i64::MAX)
            }
        };
        if keep {
            self.last.insert(key, (s.ts_ms, s.quality));
        }
        keep
    }
}

pub struct SampleBatcher {
    max_age_ms: i64,
//! Time sources. Monotonic milliseconds drive deadlines, ages and scheduling;
//! UTC milliseconds are what gets stored and exported.

use std::sync::Arc;
use std::sync::atomic::{AtomicI64, AtomicU64, Ordering};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

pub trait Clock: Send + Sync {
    /// Monotonic milliseconds since an arbitrary origin. Never goes backwards.
    fn mono_ms(&self) -> u64;
    /// Wall-clock UTC milliseconds since the Unix epoch.
    fn utc_ms(&self) -> i64;
    /// Wait for `ms` milliseconds. A manual clock advances instead of sleeping.
    fn sleep_ms(&self, ms: u64);
}

/// Real clock for the app and the training simulator.
#[derive(Debug)]
pub struct SystemClock {
    origin: Instant,
}

impl SystemClock {
    pub fn new() -> Self {
        Self { origin: Instant::now() }
    }

    pub fn shared() -> Arc<dyn Clock> {
        Arc::new(Self::new())
    }
}

impl Default for SystemClock {
    fn default() -> Self {
        Self::new()
    }
}

impl Clock for SystemClock {
    fn mono_ms(&self) -> u64 {
        u64::try_from(self.origin.elapsed().as_millis()).unwrap_or(u64::MAX)
    }

    fn utc_ms(&self) -> i64 {
        match SystemTime::now().duration_since(UNIX_EPOCH) {
            Ok(d) => i64::try_from(d.as_millis()).unwrap_or(i64::MAX),
            Err(_) => 0,
        }
    }

    fn sleep_ms(&self, ms: u64) {
        if ms > 0 {
            std::thread::sleep(Duration::from_millis(ms));
        }
    }
}

