//! Trend series for display (PRD R14, research/02 §7).
//!
//! Gaps are gaps: every non-GOOD sample, and every interval without samples
//! longer than `max_gap_ms`, becomes one `None` point plus a [`Gap`] with its
//! reason. Long ranges are decimated min-max per bucket (pixel column) inside
//! each run of GOOD samples, so spikes survive and nothing is drawn across a gap.
//! LTTB or averaging is never used here.

use crate::quality::Quality;
use serde::Serialize;

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TrendInput {
    pub ts_ms: i64,
    /// Engineering value; only used when `quality` is GOOD.
    pub value: Option<f64>,
    pub quality: Quality,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Gap {
    pub from_ms: i64,
    pub to_ms: i64,
    /// Quality text of the first bad sample (`TIMEOUT`, `EXCEPTION 02`, ...) or `NO_DATA`.
    pub reason: String,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct TrendSeries {
    pub t: Vec<i64>,
    pub v: Vec<Option<f64>>,
    pub gaps: Vec<Gap>,
    /// True when min-max decimation was applied.
    pub decimated: bool,
    /// Samples in the requested range before decimation.
    pub raw_count: usize,
}

pub const NO_DATA: &str = "NO_DATA";

fn good_value(s: &TrendInput) -> Option<f64> {
    if s.quality.is_good() {
        s.value.filter(|v| v.is_finite())
    } else {
        None
    }
}

struct Builder {
    from: i64,
    span: i128,
    buckets: i128,
    decimate: bool,
    out: TrendSeries,
    /// Current (bucket, min, max) inside the current run.
    cell: Option<(i128, (i64, f64), (i64, f64))>,
}

impl Builder {
    fn bucket(&self, ts: i64) -> i128 {
        let off = i128::from(ts) - i128::from(self.from);
        (off * self.buckets / self.span).clamp(0, self.buckets - 1)
    }

    fn push(&mut self, t: i64, v: Option<f64>) {
        self.out.t.push(t);
        self.out.v.push(v);
    }

    fn flush_cell(&mut self) {
        if let Some((_, lo, hi)) = self.cell.take() {
            let (a, b) = if lo.0 <= hi.0 { (lo, hi) } else { (hi, lo) };
            self.push(a.0, Some(a.1));
            if a != b {
                self.push(b.0, Some(b.1));
            }
        }
    }

    fn good(&mut self, ts: i64, v: f64) {
        if !self.decimate {
            self.push(ts, Some(v));
            return;
        }
        let b = self.bucket(ts);
        match &mut self.cell {
            Some((cb, lo, hi)) if *cb == b => {
                if v < lo.1 {
                    *lo = (ts, v);
                }
                if v > hi.1 {
                    *hi = (ts, v);
                }
            }
            _ => {
                self.flush_cell();
                self.cell = Some((b, (ts, v), (ts, v)));
            }
        }
    }

    fn gap(&mut self, null_at: i64, gap: Gap) {
        self.flush_cell();
        self.push(null_at, None);
        self.out.gaps.push(gap);
    }
}

/// Build the display series for samples in `[from_ms, to_ms)`.
/// `samples` must be in time order (the historian returns them so).
pub fn decimate(samples: &[TrendInput], from_ms: i64, to_ms: i64, buckets: usize, max_gap_ms: u64) -> TrendSeries {
    let in_range: Vec<&TrendInput> = samples
        .iter()
        .filter(|s| s.ts_ms >= from_ms && s.ts_ms < to_ms)
        .collect();
    let buckets = buckets.clamp(1, 100_000);
    let good_count = in_range.iter().filter(|s| good_value(s).is_some()).count();
    let mut b = Builder {
        from: from_ms,
        span: (i128::from(to_ms) - i128::from(from_ms)).max(1),
        buckets: buckets as i128,
        decimate: good_count > 2 * buckets,
        out: TrendSeries {
            raw_count: in_range.len(),
            ..TrendSeries::default()
        },
        cell: None,
    };
    b.out.decimated = b.decimate;
    let max_gap = i64::try_from(max_gap_ms).unwrap_or(i64::MAX);
    // Last GOOD sample time while in a run; open gap start + reason while in a gap.
    let mut last_good: Option<i64> = None;
    let mut open_gap: Option<(i64, String)> = None;
    let mut last_ts: Option<i64> = None;
    for s in in_range {
        last_ts = Some(s.ts_ms);
        match good_value(s) {
            Some(v) => {
                if let Some((start, reason)) = open_gap.take() {
                    // Close the gap at this first GOOD sample.
                    if let Some(g) = b.out.gaps.last_mut()
                        && g.from_ms == start
                    {
                        g.to_ms = s.ts_ms;
                        g.reason = reason;
                    }
                } else if let Some(prev) = last_good
                    && s.ts_ms.saturating_sub(prev) > max_gap
                {
                    let mid = prev + (s.ts_ms - prev) / 2;
                    b.gap(
                        mid,
                        Gap {
                            from_ms: prev,
                            to_ms: s.ts_ms,
                            reason: NO_DATA.into(),
                        },
                    );
                }
                b.good(s.ts_ms, v);
                last_good = Some(s.ts_ms);
            }
            None => {
                if open_gap.is_none() {
                    let reason = if s.quality.is_good() {
                        // GOOD without a usable value cannot be drawn either.
                        Quality::DecodeError.to_string()
                    } else {
                        s.quality.to_string()
                    };
                    let from = last_good.unwrap_or(s.ts_ms);
                    b.gap(
                        s.ts_ms,
                        Gap {
                            from_ms: from,
                            to_ms: s.ts_ms,
                            reason: reason.clone(),
                        },
                    );
                    open_gap = Some((from, reason));
                }
                last_good = None;
            }
        }
    }
    b.flush_cell();
    // A gap still open at the end lasts at least until the last bad sample.
    if let (Some((start, _)), Some(end)) = (open_gap, last_ts)
        && let Some(g) = b.out.gaps.last_mut()
        && g.from_ms == start
    {
        g.to_ms = g.to_ms.max(end);
    }
    b.out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn g(ts: i64, v: f64) -> TrendInput {
        TrendInput {
            ts_ms: ts,
            value: Some(v),
            quality: Quality::Good,
        }
    }
    fn bad(ts: i64, q: Quality) -> TrendInput {
        TrendInput {
            ts_ms: ts,
            value: Some(99.0),
            quality: q,
        }
    }

    #[test]
    fn timeout_breaks_the_line_with_its_reason() {
        let s = [
            g(0, 1.0),
            g(1000, 2.0),
            bad(2000, Quality::Timeout),
            bad(3000, Quality::Timeout),
            g(4000, 3.0),
        ];
        let out = decimate(&s, 0, 10_000, 100, 5_000);
        assert_eq!(out.t, vec![0, 1000, 2000, 4000]);
        assert_eq!(out.v, vec![Some(1.0), Some(2.0), None, Some(3.0)]);
        assert_eq!(
            out.gaps,
            vec![Gap {
                from_ms: 1000,
                to_ms: 4000,
                reason: "TIMEOUT".into()
            }]
        );
        assert!(!out.decimated);
    }

    #[test]
    fn missing_samples_become_no_data_gaps() {
        let s = [g(0, 1.0), g(1000, 1.0), g(20_000, 2.0)];
        let out = decimate(&s, 0, 30_000, 100, 3_000);
        assert_eq!(out.v, vec![Some(1.0), Some(1.0), None, Some(2.0)]);
        assert_eq!(out.gaps[0].reason, NO_DATA);
        assert_eq!((out.gaps[0].from_ms, out.gaps[0].to_ms), (1000, 20_000));
    }

    #[test]
    fn bad_values_are_never_drawn() {
        let s = [bad(0, Quality::Stale), bad(10, Quality::Exception(2))];
        let out = decimate(&s, 0, 100, 10, 1000);
        assert_eq!(out.v, vec![None]);
        assert_eq!(out.gaps[0].reason, "STALE");
        assert_eq!(out.gaps[0].to_ms, 10);
    }

    #[test]
    fn decimation_keeps_spikes() {
        let mut s: Vec<TrendInput> = (0..10_000).map(|i| g(i, 1.0)).collect();
        s[5_123].value = Some(500.0);
        s[7_001].value = Some(-500.0);
        let out = decimate(&s, 0, 10_000, 50, 10);
        assert!(out.decimated);
        assert!(out.v.len() <= 100);
        assert!(out.v.contains(&Some(500.0)) && out.v.contains(&Some(-500.0)));
        assert!(out.t.windows(2).all(|w| w[0] <= w[1]));
    }

    #[test]
    fn out_of_range_samples_ignored() {
        let s = [g(-5, 1.0), g(5, 2.0), g(100, 3.0)];
        let out = decimate(&s, 0, 100, 10, 1000);
        assert_eq!(out.v, vec![Some(2.0)]);
        assert_eq!(out.raw_count, 1);
    }
}

//! Trend decimation properties T1–T5 (app-shell-desktop design §4).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use buslink_core::quality::Quality;
use buslink_core::rng::SplitMix64;
use buslink_core::testkit::check;
use buslink_core::trend::{TrendInput, TrendSeries, decimate};
use std::collections::HashMap;

struct Case {
    samples: Vec<TrendInput>,
    from: i64,
    to: i64,
    buckets: usize,
    max_gap: u64,
}

fn gen_case(rng: &mut SplitMix64) -> Case {
    let n = rng.range_usize(0, 3000);
    let mut ts = rng.range_usize(0, 1000) as i64;
    let mut samples = Vec::with_capacity(n);
    for _ in 0..n {
        ts += rng.range_usize(0, 40) as i64;
        if rng.chance(20) {
            ts += rng.range_usize(100, 2000) as i64; // occasional hole
        }
        let quality = match rng.range_usize(0, 30) {
            0 => Quality::Timeout,
            1 => Quality::CrcError,
            2 => Quality::Exception(2),
            3 => Quality::Stale,
            4 => Quality::DecodeError,
            _ => Quality::Good,
        };
        let value = if rng.chance(5) {
            None
        } else {
            Some((rng.range_usize(0, 20_000) as f64 - 10_000.0) / 10.0)
        };
        samples.push(TrendInput { ts_ms: ts, value, quality });
    }
    let from = rng.range_usize(0, 500) as i64;
    let to = ts - rng.range_usize(0, 500) as i64 + 1;
    Case {
        samples,
        from,
        to: to.max(from + 1),
        buckets: rng.range_usize(1, 400),
        max_gap: rng.range_usize(50, 1500) as u64,
    }
}

fn run(c: &Case) -> TrendSeries {
    decimate(&c.samples, c.from, c.to, c.buckets, c.max_gap)
}

fn in_range(c: &Case) -> Vec<&TrendInput> {
    c.samples
        .iter()
        .filter(|s| s.ts_ms >= c.from && s.ts_ms < c.to)
        .collect()
}

fn is_good(s: &TrendInput) -> bool {
    s.quality.is_good() && s.value.is_some_and(f64::is_finite)
}

/// Runs of GOOD samples as the decimator must see them.
fn runs<'a>(c: &'a Case) -> Vec<Vec<&'a TrendInput>> {
    let mut out: Vec<Vec<&TrendInput>> = Vec::new();
    let mut cur: Vec<&TrendInput> = Vec::new();
    for s in in_range(c) {
        if !is_good(s) {
            if !cur.is_empty() {
                out.push(std::mem::take(&mut cur));
            }
            continue;
        }
        if let Some(prev) = cur.last()
            && (s.ts_ms - prev.ts_ms) as u64 > c.max_gap
        {
            out.push(std::mem::take(&mut cur));
        }
        cur.push(s);
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

#[test]
fn t1_values_are_real_good_samples() {
    check("trend T1", 500, |rng| {
        let c = gen_case(rng);
        let out = run(&c);
        let good: Vec<(i64, f64)> = in_range(&c)
            .into_iter()
            .filter(|s| is_good(s))
            .map(|s| (s.ts_ms, s.value.unwrap()))
            .collect();
        for (t, v) in out.t.iter().zip(&out.v) {
            if let Some(v) = v {
                assert!(good.iter().any(|(gt, gv)| gt == t && gv == v), "value {v} at {t} is not a GOOD sample");
            }
        }
    });
}

#[test]
fn t2_nothing_drawn_across_a_gap() {
    check("trend T2", 500, |rng| {
        let c = gen_case(rng);
        let out = run(&c);
        let samples = in_range(&c);
        let pts: Vec<(i64, Option<f64>)> = out.t.iter().copied().zip(out.v.iter().copied()).collect();
        for w in pts.windows(2) {
            let ((a, va), (b, vb)) = (w[0], w[1]);
            if va.is_none() || vb.is_none() {
                continue;
            }
            assert!(
                !samples.iter().any(|s| s.ts_ms > a && s.ts_ms < b && !is_good(s)),
                "bad sample between {a} and {b}"
            );
            // Between two drawn points every consecutive pair of input samples is within max_gap.
            let inner: Vec<i64> = samples
                .iter()
                .filter(|s| s.ts_ms >= a && s.ts_ms <= b)
                .map(|s| s.ts_ms)
                .collect();
            for p in inner.windows(2) {
                assert!((p[1] - p[0]) as u64 <= c.max_gap, "hole {}..{} drawn over", p[0], p[1]);
            }
        }
    });
}

#[test]
fn t3_extremes_of_every_bucket_kept() {
    check("trend T3", 500, |rng| {
        let c = gen_case(rng);
        let out = run(&c);
        let drawn: Vec<(i64, f64)> = out
            .t
            .iter()
            .zip(&out.v)
            .filter_map(|(t, v)| v.map(|v| (*t, v)))
            .collect();
        let span = i128::from(c.to - c.from).max(1);
        for r in runs(&c) {
            let mut cells: HashMap<i128, (f64, f64)> = HashMap::new();
            for s in &r {
                let b = (i128::from(s.ts_ms - c.from) * c.buckets as i128 / span).clamp(0, c.buckets as i128 - 1);
                let v = s.value.unwrap();
                let e = cells.entry(b).or_insert((v, v));
                e.0 = e.0.min(v);
                e.1 = e.1.max(v);
            }
            let ts: Vec<i64> = r.iter().map(|s| s.ts_ms).collect();
            let (lo, hi) = (ts[0], ts[ts.len() - 1]);
            for (min, max) in cells.values() {
                for want in [min, max] {
                    assert!(
                        drawn.iter().any(|(t, v)| v == want && *t >= lo && *t <= hi),
                        "extreme {want} of a run/bucket missing"
                    );
                }
            }
        }
    });
}

#[test]
fn t4_t5_bounded_and_sorted() {
    check("trend T4/T5", 500, |rng| {
        let c = gen_case(rng);
        let out = run(&c);
        assert_eq!(out.t.len(), out.v.len());
        assert!(out.t.windows(2).all(|w| w[0] <= w[1]), "times not sorted");
        let nulls = out.v.iter().filter(|v| v.is_none()).count();
        assert_eq!(nulls, out.gaps.len(), "one null per gap");
        for g in &out.gaps {
            assert!(g.from_ms <= g.to_ms);
        }
        if out.decimated {
            let values = out.v.len() - nulls;
            assert!(values <= 2 * (c.buckets + runs(&c).len()), "{values} values");
        }
    });
}

#[test]
fn hundred_thousand_samples_decimate_quickly() {
    let samples: Vec<TrendInput> = (0..100_000)
        .map(|i| TrendInput {
            ts_ms: i * 1000,
            value: Some((i as f64 / 50.0).sin()),
            quality: if i % 9_973 == 0 { Quality::Timeout } else { Quality::Good },
        })
        .collect();
    let started = std::time::Instant::now();
    let out = decimate(&samples, 0, 100_000_000, 1200, 3000);
    let took = started.elapsed();
    eprintln!("decimate 100k → {} points in {took:?}", out.t.len());
    assert!(out.decimated && out.t.len() <= 2 * (1200 + 12) + 12);
    assert!(took.as_millis() < 1000, "took {took:?}");
}

