                acked_since_activation = false;
            }
            if rng.chance(100) {
                e.ack("a1", t).unwrap();
                acked_since_activation = true;
            }
            if !acked_since_activation {
                assert_ne!(e.state("a1", t), Some(AlarmState::Normal));
            }
