                ErrorKind::NoDevice => TransportError::Disconnected(format!("port {name} not found")),
                ErrorKind::Io(std::io::ErrorKind::PermissionDenied) => {
                    TransportError::Io(format!("port {name} is busy or access was denied (another program may own it)"))
                }
                _ if e.description.to_ascii_lowercase().contains("access is denied") => {
                    TransportError::Io(format!("port {name} is busy or access was denied (another program may own it)"))
                }
                _ => TransportError::Io(format!("{name}: {}", e.description)),
            })?;
