    poll_interval_ms: Option<u64>,
}

#[tauri::command]
pub fn add_device(state: State<'_, AppState>, req: AddDeviceReq) -> R<String> {
    let s = &state.session;
    let profile = s
        .profile(&req.profile_key)
        .ok_or_else(|| format!("unknown profile '{}'", req.profile_key))?;
    let link = s
        .links()
        .into_iter()
        .find(|l| l.id == req.link_id)
        .ok_or_else(|| format!("unknown link '{}'", req.link_id))?;
    let id = s.suggest_device_id(&profile.profile_id, req.unit_id);
    let name = req
        .name
        .map(|n| n.trim().chars().take(80).collect::<String>())
        .filter(|n| !n.is_empty())
        .unwrap_or_else(|| format!("{} #{}", profile.model.get("en"), req.unit_id));
    // Build from a throwaway config only to pick profile defaults; the session re-checks against the real link.
    let cfg = LinkConfig {
        id: link.id.clone(),
        kind: if link.kind == "tcp" {
            LinkKind::Tcp {
                host: String::new(),
                port: 502,
            }
        } else {
            LinkKind::Simulator {
                name: String::new(),
                serial: SerialSettings::default_9600_8n1(),
            }
        },
        min_inter_frame_ms: 0,
    };
    let mut d = DeviceInstance::from_profile(&id, &name, &cfg, &profile);
    d.unit_id = req.unit_id;
    if let Some(ms) = req.poll_interval_ms {
        d.poll_interval_ms = ms;
    }
    s.add_device(d).map_err(err)?;
    Ok(id)
}

