    const on = Number(onIn.value);
    const off = Number(offIn.value);
    let bad = false;
    if (!tagSel.value) {
      fTag.error(t("alarm.err.tag"));
      bad = true;
    }
    if (limitIn.value.trim() === "" || !Number.isFinite(limit)) {
