      bad = true;
    }
    if (!Number.isFinite(deadband) || deadband < 0) {
      fDb.error(t("alarm.err.deadband"));
      bad = true;
    }
    for (const [f, v] of [[fOn, on], [fOff, off]] as const) {
      if (!Number.isFinite(v) || v < 0 || v > 3600) {
        f.error(t("alarm.err.delay"));
