      }
    }
    if (bad) return;
    const kind = kindSel.value as AlarmKind;
    try {
      await api.alarmAdd({
        id: `${devSel.value}.${tagSel.value}.${kind.toLowerCase()}.${Date.now().toString(36)}`,
        device_id: devSel.value,
