    );
    return f.sort((a, b) =>
      sort === "priority"
        ? a.priority - b.priority || (b.activated_ms ?? 0) - (a.activated_ms ?? 0)
        : (b.activated_ms ?? b.last_change_ms) - (a.activated_ms ?? a.last_change_ms),
    );
  }

  function renderLists() {
    preserveFocus(processBox, () => {
      clear(processBox);
