.prio-shape polygon {
  stroke: var(--text);
  stroke-width: 1;
}
.prio-shape.p1 polygon {
  fill: var(--alarm-1);
}
.prio-shape.p1 text {
  fill: var(--alarm-1-text);
}
.prio-shape.p2 polygon {
  fill: var(--alarm-2);
}
.prio-shape.p2 text {
  fill: var(--alarm-2-text);
}
.prio-shape.p3 polygon {
  fill: var(--alarm-3);
}
.prio-shape.p3 text {
  fill: var(--alarm-3-text);
}
.support {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.85rem;
