  padding: 0.2rem 0.6rem;
  border: 2px dashed var(--info);
  border-radius: 4px;
  font-weight: 700;
}
.sim-banner .support-shape {
  stroke: var(--info);
}
.astate {
  font-weight: 600;
}
.astate-unacked,
.astate-rtn_unacked {
  text-decoration: underline wavy;
}

/* ---------- dashboard ---------- */
.summary {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}
.summary-prio {
  display: inline-flex;
  align-items: center;
}
.paused-banner {
  padding: 0.5rem 0.75rem;
  border: 2px dashed var(--text);
  font-weight: 700;
  background: var(--surface);
}
.device-card.disconnected .tile-grid {
