}
.device-head h3 {
  margin: 0;
}
.head-label {
  font-size: 0.85rem;
  color: var(--text-muted);
}
.head-links {
  display: flex;
  gap: 1rem;
  margin-left: auto;
}
.tile-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 15rem), 1fr));
  gap: 0.5rem;
}
.compact .tile-grid {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 11rem), 1fr));
}
.compact .tile {
  padding: 0.35rem 0.5rem;
}
.compact .bar-scale,
