.tile.q-disc {
  border: 2px solid var(--text);
  background-image: repeating-linear-gradient(45deg, transparent 0 8px, rgba(0, 0, 0, 0.06) 8px 12px);
}
.tile.alarm-p1 {
  box-shadow: inset 4px 0 0 var(--alarm-1);
}
.tile.alarm-p2 {
  box-shadow: inset 4px 0 0 var(--alarm-2);
}
.tile.alarm-p3 {
  box-shadow: inset 4px 0 0 var(--alarm-3);
}

/* Analog bar: grey track, shaded normal band, limit ticks, value marker. */
.bar {
  margin: 0.35rem 0 0.15rem;
}
.bar-track {
  position: relative;
  height: 0.75rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 2px;
}
.bar-band {
  position: absolute;
  top: 0;
  bottom: 0;
  background: var(--band);
}
.bar-tick {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  background: var(--text);
}
.bar-marker {
  position: absolute;
  top: -5px;
  bottom: -5px;
  width: 4px;
  margin-left: -2px;
  background: var(--text);
  border: 1px solid var(--surface);
}
.tile.q-stale .bar-marker,
.tile.q-bad .bar-marker,
.tile.q-disc .bar-marker {
  background: transparent;
  border: 2px dashed var(--text);
}
.bar-scale {
  display: flex;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ---------- connect / library ---------- */
.training-cta {
  border: 2px dashed var(--info);
}
.profile-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 22rem), 1fr));
  gap: 0 1rem;
}
.form-grid.compact {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 9rem), 1fr));
}

/* ---------- trends ---------- */
.trend-layout {
  display: grid;
  grid-template-columns: minmax(12rem, 18rem) 1fr;
  gap: 1rem;
}
.tag-picker {
  margin: 0.75rem 0;
  max-height: 70vh;
  overflow: auto;
}
.pick-device {
  font-weight: 700;
  margin: 0.5rem 0 0.15rem;
}
.pick-group label.check {
  display: flex;
}
.trend-main {
  min-width: 0;
}
.chart {
  margin: 0.75rem 0;
  padding: 0.5rem;
}
.chart-tip {
  white-space: pre-line;
  font-size: 0.8rem;
  min-height: 2.6em;
  color: var(--text-muted);
}
.uplot,
.u-legend {
  color: var(--text);
  font-family: inherit;
}
.u-legend .u-marker {
  border-width: 2px !important;
}
.u-select {
  background: rgba(0, 119, 187, 0.15);
}
.gap-list {
  padding-left: 1.2rem;
}

/* ---------- inspector ---------- */
.inspector-table td,
.frames-table td {
  font-size: 0.85rem;
}
.order-profile {
  font-weight: 700;
  outline: 2px solid var(--line);
  outline-offset: -2px;
}
.tag-profile {
  font-weight: 400;
  color: var(--text-muted);
}
.frame-bad td:first-child {
  box-shadow: inset 4px 0 0 var(--quality-bad);
}

/* ---------- alarms ---------- */
.arow.astate-unacked th,
.arow.astate-rtn_unacked th {
  font-weight: 700;
}
.arow.p1.astate-unacked td:first-child {
  box-shadow: inset 4px 0 0 var(--alarm-1);
}
.arow.p2.astate-unacked td:first-child {
  box-shadow: inset 4px 0 0 var(--alarm-2);
}
.arow.p3.astate-unacked td:first-child {
  box-shadow: inset 4px 0 0 var(--alarm-3);
}

/* ---------- training ---------- */
.fault-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 20rem), 1fr));
  gap: 0 1rem;
}
.exercises {
  padding-left: 0;
  list-style: none;
}

/* ---------- narrow screens (Android, 360 px) ---------- */
@media (max-width: 720px) {
  .trend-layout {
    grid-template-columns: 1fr;
  }
  .tag-picker {
    max-height: 14rem;
  }
  button.primary,
  .button.primary,
  .nav a {
    min-height: 2.75rem; /* 44 px primary targets on mobile */
  }
  .settings {
    margin-left: 0;
  }
  .head-links {
    margin-left: 0;
  }
  main {
    padding: 0.5rem 0.5rem 2rem;
  }
  .card {
    padding: 0.5rem 0.6rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

// U1/U2: store buffers → uPlot series. Run with `node --test` (type stripping).
import assert from "node:assert/strict";
import { test } from "node:test";
import { align, bufferToSeries, NO_DATA } from "./series.ts";
import type { TrendBuffer } from "./store.ts";
import type { QualityCode } from "./types.ts";

function buf(points: [number, number | null, QualityCode][]): TrendBuffer {
  return { t: points.map((p) => p[0]), v: points.map((p) => p[1]), q: points.map((p) => p[2]) };
}

test("U1 non-GOOD points become null, never a number", () => {
  const s = bufferToSeries(
    buf([
      [0, 1, "GOOD"],
      [1000, 2, "GOOD"],
      [2000, 999, "TIMEOUT"],
      [3000, 999, "TIMEOUT"],
      [4000, 3, "GOOD"],
    ]),
    0,
    4000,
    5000,
  );
  assert.deepEqual(s.v, [1, 2, null, 3]);
  assert.deepEqual(s.gaps, [{ from_ms: 1000, to_ms: 4000, reason: "TIMEOUT" }]);
});

test("U1 random buffers: every value comes from a GOOD point", () => {
  let seed = 7;
  const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2 ** 31) / 2 ** 31);
  const qs: QualityCode[] = ["GOOD", "GOOD", "GOOD", "TIMEOUT", "STALE", "CRC_ERROR", "EXCEPTION", "DISCONNECTED"];
  for (let c = 0; c < 200; c++) {
    let t = 0;
    const pts: [number, number | null, QualityCode][] = [];
    for (let i = 0; i < 100; i++) {
      t += Math.floor(rnd() * 3000);
      pts.push([t, Math.round(rnd() * 100), qs[Math.floor(rnd() * qs.length)] ?? "GOOD"]);
    }
    const b = buf(pts);
    const s = bufferToSeries(b, 0, t, 2000);
    s.t.forEach((x, i) => {
      const v = s.v[i];
      if (v === null || v === undefined) return;
      const j = b.t.indexOf(x);
      assert.ok(j >= 0 && b.q[j] === "GOOD" && b.v[j] === v, `value ${v} at ${x} is not GOOD`);
    });
    // U2: two consecutive drawn values never straddle a bad point or a hole longer than the threshold.
    for (let i = 1; i < s.t.length; i++) {
      const [a, bb] = [s.t[i - 1] ?? 0, s.t[i] ?? 0];
      if (s.v[i - 1] === null || s.v[i] === null) continue;
      assert.ok(bb - a <= 2000, `hole ${a}..${bb} drawn over`);
      for (let j = 0; j < b.t.length; j++) {
        const x = b.t[j] ?? 0;
        if (x > a && x < bb) assert.equal(b.q[j], "GOOD");
      }
    }
  }
});

test("U2 holes and a silent tail are NO_DATA gaps", () => {
  const s = bufferToSeries(
    buf([
      [0, 1, "GOOD"],
      [10_000, 2, "GOOD"],
    ]),
    0,
    30_000,
    3000,
  );
  assert.deepEqual(s.v, [1, null, 2]);
  assert.equal(s.gaps.length, 2);
  assert.equal(s.gaps[0]?.reason, NO_DATA);
  assert.deepEqual([s.gaps[1]?.from_ms, s.gaps[1]?.to_ms], [10_000, 30_000]);
});

test("align keeps own nulls and uses undefined only for alignment", () => {
  const a = { t: [1, 2, 3], v: [1, null, 3], gaps: [] };
  const b = { t: [2, 4], v: [5, 6], gaps: [] };
  const { x, ys } = align([a, b]);
  assert.deepEqual(x, [1, 2, 3, 4]);
  assert.deepEqual(ys[0], [1, null, 3, undefined]);
  assert.deepEqual(ys[1], [undefined, 5, undefined, 6]);
});

